import util from 'node:util';
const pesanan = { id: 1, pelanggan: { nama: 'Rina', alamat: { kota: 'Bandung', rt: { no: 3 } } } };
console.log(pesanan);
console.log(util.inspect(pesanan, { depth: null, breakLength: Infinity }));
console.log('%s pesan %d kopi', 'Rina', 2);
console.count('kopi');
console.count('kopi');

